  -print="A"                  String specifying what the output should contain, default will print all information
         "H" request headers
         "B" request body
         "h" response headers
         "b" response body
  -v, -version=true           Show Version Number

METHOD:
  bat defaults to either GET (if there is no request data) or POST (with request data).

URL:
  The only information needed to perform a request is a URL. The default scheme is http://,
  which can be omitted from the argument; example.org works just fine.

ITEM:
  Can be any of:
    Query string   key=value
    Header         key:value
    Post data      key=value
    File upload    key@/path/file

Example:

	bat beego.me

more help information please refer to https://github.com/astaxie/bat
"""

METHODS = {"GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"}
TOKEN_RE = re.compile(r"^[!#$%&'*+.^_`|~0-9A-Za-z-]+$")

class FlagExit(Exception):
    def __init__(self, code=2, err=None, usage=True, version=False):
        self.code = code
        self.err = err
        self.usage = usage
        self.version = version

class FatalExit(Exception):
    def __init__(self, file, line, msg, code=1):
        self.file = file
        self.line = line
        self.msg = msg
        self.code = code


def usage_and_exit(code=2):
    sys.stdout.write(HELP_TEXT)
    raise SystemExit(code)


def log_prefix(file, line):
    now = datetime.now().strftime("%Y/%m/%d %H:%M:%S.%f")
    return f"{now} {file}:{line}: "


def fatal(file, line, msg, code=1):
    sys.stderr.write(log_prefix(file, line) + msg + "\n")
    raise SystemExit(code)


def parse_bool_value(s):
    if s in ("1", "t", "T", "true", "TRUE", "True"):
        return True
    if s in ("0", "f", "F", "false", "FALSE", "False"):
        return False
    raise ValueError


def default_flags():
    return {
        "auth": "",
        "bench": False,
        "b.N": 1000,
        "b.C": 100,
        "body": "",
        "form": False,
        "json": True,
        "pretty": True,
        "insecure": False,
        "proxy": "",
        "print": "A",
        "version": False,
    }


def parse_flags(argv):
    flags = default_flags()
    aliases = {
        "a": "auth", "auth": "auth",
        "b": "bench", "bench": "bench",
        "b.N": "b.N", "b.C": "b.C",
        "body": "body",
        "f": "form", "form": "form",
        # The help advertises -j, but the observed binary only accepts -json.
        "json": "json",
        "p": "pretty", "pretty": "pretty",
        "i": "insecure", "insecure": "insecure",
        "proxy": "proxy",
        "print": "print",
        "v": "version", "version": "version",
    }
    types = {
        "auth": "string", "bench": "bool", "b.N": "int", "b.C": "int",
        "body": "string", "form": "bool", "json": "bool", "pretty": "bool",
        "insecure": "bool", "proxy": "string", "print": "string", "version": "bool",
    }
    i = 0
    n = len(argv)
    while i < n:
        arg = argv[i]
        if arg == "--":
            i += 1
            break
        if arg == "-" or not arg.startswith("-"):
            break
        # Go's flag package rejects a triple-minus spelling as bad syntax.
        if arg.startswith("---"):
            raise FlagExit(2, f"bad flag syntax: {arg}", True)
        dashes = 2 if arg.startswith("--") else 1
        body = arg[dashes:]
        if body == "" or body.startswith("-"):
            raise FlagExit(2, f"bad flag syntax: {arg}", True)
        if "=" in body:
            name, val = body.split("=", 1)
            has_val = True
        else:
            name, val = body, None
            has_val = False
        if name in ("h", "help"):
            raise FlagExit(2, None, True)
        if name not in aliases:
            # The diagnostic uses a single dash, even for --long.
            raise FlagExit(2, f"flag provided but not defined: -{name}", True)
        key = aliases[name]
        typ = types[key]
        if typ == "bool":
            if has_val:
                try:
                    flags[key] = parse_bool_value(val)
                except ValueError:
                    raise FlagExit(2, f"invalid boolean value \"{val}\" for -{name}: parse error", True)
            else:
                flags[key] = True
            i += 1
        elif typ == "string":
            if not has_val:
                if i + 1 >= n:
                    raise FlagExit(2, f"flag needs an argument: -{name}", True)
                val = argv[i + 1]
                i += 2
            else:
                i += 1
            flags[key] = val
        elif typ == "int":
            if not has_val:
                if i + 1 >= n:
                    raise FlagExit(2, f"flag needs an argument: -{name}", True)
                val = argv[i + 1]
                i += 2
            else:
                i += 1
            try:
                # strconv.Atoi-style decimal is enough for observed use.
                flags[key] = int(val, 10)
            except Exception:
                raise FlagExit(2, f"invalid value \"{val}\" for flag -{name}: parse error", True)
    return flags, argv[i:]


def canonical_mime_key(k):
    # Approximate Go's textproto.CanonicalMIMEHeaderKey.
    out = []
    upper = True
    for ch in k:
        if ch == '-':
            out.append(ch)
            upper = True
        else:
            if 'a' <= ch <= 'z' or 'A' <= ch <= 'Z':
                out.append(ch.upper() if upper else ch.lower())
            else:
                out.append(ch)
            upper = False
    return ''.join(out)


def split_positionals(args):
    if not args:
        return None, None, [], False
    first_up = args[0].upper()
    if first_up in METHODS:
        if len(args) < 2:
            fatal("filter.go", 35, "Miss the URL")
        return first_up, args[1], args[2:], True
    return None, args[0], args[1:], False


def parse_items(items):
    headers = []       # (raw_key, canonical_key, value)
    data = {}
    data_order = []
    file_count = 0
    for item in items:
        if ':' in item:
            k, v = item.split(':', 1)
            headers.append((k, canonical_mime_key(k), v))
        elif '=' in item:
            k, v = item.split('=', 1)
            if k not in data:
                data_order.append(k)
            data[k] = v
        elif '@' in item:
            file_count += 1
        else:
            pass
    return headers, data, data_order, file_count


def go_query_escape(s):
    return urllib.parse.quote_plus(s, safe='')


def encode_params(data, order):
    if not data:
        return ""
    # The original builds from a Go map, so order is intentionally not a
    # user-visible guarantee.  Use insertion order for stable behavior.
    pairs = []
    for k in order:
        if k in data:
            pairs.append(go_query_escape(k) + "=" + go_query_escape(data[k]))
    return "&".join(pairs)


def go_json_escape(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '<':
            out.append('\\u003c')
        elif ch == '>':
            out.append('\\u003e')
        elif ch == '&':
            out.append('\\u0026')
        elif o < 0x20:
            out.append('\\u%04x' % o)
        elif o == 0x2028:
            out.append('\\u2028')
        elif o == 0x2029:
            out.append('\\u2029')
        else:
            out.append(ch)
    return ''.join(out)


def encode_json_body(data):
    parts = []
    for k in sorted(data.keys()):
        parts.append('"' + go_json_escape(k) + '":"' + go_json_escape(data[k]) + '"')
    return ('{' + ','.join(parts) + '}\n').encode('utf-8')


def validate_header_name(name):
    return bool(name) and bool(TOKEN_RE.match(name))


def make_basic_auth(auth):
    if auth == "":
        return None
    parts = auth.split(':')
    if len(parts) == 1:
        user, pw = parts[0], ""
    elif len(parts) == 2:
        user, pw = parts[0], parts[1]
    else:
        user = parts[0]
        pw = ''.join(p + ':' for p in parts[1:])
    token = base64.b64encode((user + ':' + pw).encode('utf-8')).decode('ascii')
    return "Basic " + token


def normalize_url(url):
    if not url.startswith("http"):
        url = "http://" + url
    return url


def append_query(url, encoded):
    if not encoded:
        return url
    parts = urllib.parse.urlsplit(url)
    q = parts.query
    if q:
        q = q + "&" + encoded
    else:
        q = encoded
    return urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path, q, parts.fragment))


def build_request(flags, method, url, headers_items, data, data_order, file_count):
    explicit_method = method is not None
    has_request_data = bool(data) or file_count > 0
    if method is None:
        method = "POST" if has_request_data else "GET"
    url = normalize_url(url)

    # Explicit GET turns key=value items into query string. Other methods use a body.
    if method == "GET" and data:
        url = append_query(url, encode_params(data, data_order))

    headers = {
        "User-Agent": USER_AGENT,
        "Accept": "application/json",
        "Accept-Encoding": "gzip, deflate",
    }
    host_override = None
    for raw, ck, val in headers_items:
        if raw == "Host":
            host_override = val
            continue
        # net/http ignores Header["Host"] for outgoing requests unless Request.Host is set.
        if ck == "Host":
            continue
        headers[ck] = val

    body_bytes = None
    raw_body = flags.get("body", "")
    if raw_body != "":
        body_bytes = raw_body.encode('utf-8')

    if method != "GET" and data:
        if flags.get("form", False):
            if raw_body == "":
                body_bytes = encode_params(data, data_order).encode('utf-8')
                headers["Content-Type"] = "application/x-www-form-urlencoded"
            # With -body and -form, the observed tool leaves Content-Type alone.
        else:
            headers["Content-Type"] = "application/json"
            if raw_body == "":
                body_bytes = encode_json_body(data)

    # File-upload items are counted for default POST, but otherwise ignored; a POST
    # with no real body still sends Content-Length: 0.
    if body_bytes is None:
        if method in ("POST", "PUT", "PATCH"):
            body_bytes = b""
        elif explicit_method and method in ("POST", "PUT", "PATCH"):
            body_bytes = b""
        elif (method == "POST" and file_count > 0):
            body_bytes = b""

    auth_header = make_basic_auth(flags.get("auth", ""))
    if auth_header:
        headers["Authorization"] = auth_header

    # Validate headers similarly to net/http just before sending.
    for k in list(headers.keys()):
        if not validate_header_name(k):
            raise ValueError(f'net/http: invalid header field name "{k}"')

    return method, url, headers, body_bytes, host_override


def parse_proxy(proxy):
    if not proxy:
        return None
    if '://' not in proxy:
        fatal("bat.go", 182, f'Proxy Url parse errparse "{proxy}": first path segment in URL cannot contain colon')
    p = urllib.parse.urlsplit(proxy)
    if not p.scheme or not p.hostname:
        fatal("bat.go", 182, f'Proxy Url parse errparse "{proxy}": missing protocol scheme')
    return p


def connection_for(url_parts, flags, proxy_parts=None):
    scheme = url_parts.scheme
    if proxy_parts is not None:
        host = proxy_parts.hostname
        port = proxy_parts.port or (443 if proxy_parts.scheme == 'https' else 80)
        if proxy_parts.scheme == 'https':
            ctx = ssl._create_unverified_context() if flags.get('insecure') else ssl.create_default_context()
            return http.client.HTTPSConnection(host, port, timeout=30, context=ctx)
        return http.client.HTTPConnection(host, port, timeout=30)
    host = url_parts.hostname
    port = url_parts.port
    if scheme == 'http':
        return http.client.HTTPConnection(host, port or 80, timeout=30)
    if scheme == 'https':
        ctx = ssl._create_unverified_context() if flags.get('insecure') else ssl.create_default_context()
        return http.client.HTTPSConnection(host, port or 443, timeout=30, context=ctx)
    raise ValueError(f'unsupported protocol scheme "{scheme}"')


def request_target(parts, proxy_parts=None):
    path = parts.path or "/"
    if parts.query:
        path += "?" + parts.query
    if proxy_parts is not None and parts.scheme == 'http':
        # Go's HTTP proxy transport sends an absolute-form URI to an HTTP proxy.
        return urllib.parse.urlunsplit((parts.scheme, parts.netloc, parts.path or '/', parts.query, ''))
    return path


def method_for_error(method):
    if not method:
        return "Get"
    return method[:1].upper() + method[1:].lower()


def format_http_error(method, url, exc):
    # A compact approximation of Go net/http errors for common local failures.
    m = method_for_error(method)
    if isinstance(exc, ConnectionRefusedError):
        return f'{m} "{url}": dial tcp: connect: connection refused'
    if isinstance(exc, socket.gaierror):
        return f'{m} "{url}": dial tcp: lookup {getattr(exc, "filename", "") or ""}: no such host'
    return f'{m} "{url}": {exc}'


def do_http_request(flags, method, url, headers, body_bytes, host_override, follow_redirects=True):
    proxy_parts = parse_proxy(flags.get('proxy', ''))
    cur_method = method
    cur_url = url
    cur_body = body_bytes
    cur_headers = dict(headers)
    redirects = 0
    while True:
        parts = urllib.parse.urlsplit(cur_url)
        if not parts.scheme or (parts.scheme not in ('http', 'https')):
            raise ValueError(f'unsupported protocol scheme "{parts.scheme}"')
        if not parts.hostname:
            raise ValueError('http: no Host in request URL')
        conn = connection_for(parts, flags, proxy_parts)
        target = request_target(parts, proxy_parts)
        send_headers = dict(cur_headers)
        if host_override is not None:
            send_headers['Host'] = host_override
        try:
            conn.request(cur_method, target, body=cur_body, headers=send_headers)
            resp = conn.getresponse()
            raw = resp.read()
            resp_headers = {k: v for k, v in resp.getheaders()}
            status = resp.status
            loc = resp_headers.get('Location') or resp_headers.get('location')
            conn.close()
        except Exception:
            try:
                conn.close()
            except Exception:
                pass
            raise
        if follow_redirects and status in (301, 302, 303, 307, 308) and loc and redirects < 10:
            redirects += 1
            cur_url = urllib.parse.urljoin(cur_url, loc)
            if status in (301, 302, 303) and cur_method not in ('GET', 'HEAD'):
                cur_method = 'GET'
                cur_body = None
                cur_headers.pop('Content-Type', None)
                cur_headers.pop('Content-Length', None)
            continue
        enc = resp_headers.get('Content-Encoding') or resp_headers.get('content-encoding') or ''
        if enc.lower() == 'gzip':
            try:
                raw = gzip.decompress(raw)
            except Exception:
                pass
        return status, resp_headers, raw


def go_json_error_message(text, exc):
    if text.strip() == "":
        return "unexpected end of JSON input"
    s = text.lstrip()
    if not s:
        return "unexpected end of JSON input"
    first = s[0]
    allowed = '{["-0123456789tfn'
    if first not in allowed:
        return f"invalid character '{first}' looking for beginning of value"
    if first == '{':
        rest = s[1:].lstrip()
        if rest and rest[0] not in ('}', '"'):
            return f"invalid character '{rest[0]}' looking for beginning of object key string"
    # Fall back to Python's message; exact parse errors are rarely user-facing in tests.
    return str(exc)


def json_indent_preserve(text):
    # Validate first; parse_constant rejects NaN/Infinity accepted by Python but not JSON.
    try:
        json.loads(text, parse_constant=lambda x: (_ for _ in ()).throw(ValueError("invalid constant")))
    except Exception as e:
        raise ValueError(go_json_error_message(text, e))

    # Drop leading JSON whitespace, preserve trailing whitespace like encoding/json.Indent.
    start = 0
    while start < len(text) and text[start] in ' \t\r\n':
        start += 1
    end = len(text) - 1
    while end >= start and text[end] in ' \t\r\n':
        end -= 1
    trailing = text[end+1:] if end + 1 < len(text) else ''
    s = text[start:end+1]
    out = []
    level = 0
    i = 0
    n = len(s)

    def skip_ws(j):
        while j < n and s[j] in ' \t\r\n':
            j += 1
        return j

    def copy_string(j):
        k = j + 1
        esc = False
        while k < n:
            ch = s[k]
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                return s[j:k+1], k + 1
            k += 1
        return s[j:], n

    while i < n:
        c = s[i]
        if c in ' \t\r\n':
            i += 1
            continue
        if c == '"':
            st, i = copy_string(i)
            out.append(st)
            continue
        if c in '{[':
            close = '}' if c == '{' else ']'
            j = skip_ws(i + 1)
            out.append(c)
            if j < n and s[j] == close:
                out.append(close)
                i = j + 1
            else:
                level += 1
                out.append('\n' + '  ' * level)
                i += 1
            continue
        if c in '}]':
            level = max(0, level - 1)
            out.append('\n' + '  ' * level + c)
            i += 1
            continue
        if c == ',':
            out.append(',\n' + '  ' * level)
            i += 1
            continue
        if c == ':':
            out.append(': ')
            i += 1
            continue
        # number/literal token
        j = i
        while j < n and s[j] not in ' \t\r\n{}[],:':
            j += 1
        out.append(s[i:j])
        i = j
    return ''.join(out) + trailing


def output_response(flags, resp_headers, body):
    sys.stdout.buffer.write(b"\n")
    sys.stdout.buffer.flush()
    ctype = ''
    for k, v in resp_headers.items():
        if k.lower() == 'content-type':
            ctype = v
            break
    if flags.get('pretty', True) and ('json' in ctype):
        try:
            text = body.decode('utf-8')
            indented = json_indent_preserve(text)
        except Exception as e:
            fatal("http.go", 122, "Response Json Indent: " + str(e))
        sys.stdout.buffer.write(indented.encode('utf-8'))
    else:
        sys.stdout.buffer.write(body)
    sys.stdout.buffer.flush()


def run_once(flags, method, url, headers_items, data, data_order, file_count, output=True):
    try:
        req_method, req_url, req_headers, req_body, host_override = build_request(
            flags, method, url, headers_items, data, data_order, file_count)
    except ValueError as e:
        # Construction errors are reported in the same place as client.Do errors.
        req_method = method or ('POST' if data or file_count else 'GET')
        req_url = normalize_url(url)
        fatal("bat.go", 215, f"can't get the url {method_for_error(req_method)} \"{req_url}\": {e}")
    try:
        status, resp_headers, body = do_http_request(flags, req_method, req_url, req_headers, req_body, host_override)
    except Exception as e:
        fatal("bat.go", 215, "can't get the url " + format_http_error(req_method, req_url, e))
    if output:
        output_response(flags, resp_headers, body)
    return status, len(body)


def percentile(vals, pct):
    if not vals:
        return 0.0
    vals = sorted(vals)
    idx = int((pct / 100.0) * len(vals))
    if idx >= len(vals):
        idx = len(vals) - 1
    return vals[idx]


def run_bench(flags, method, url, headers_items, data, data_order, file_count):
    total_n = flags.get('b.N', 1000)
    conc = flags.get('b.C', 100)
    if total_n <= 0:
        return
    if conc <= 0:
        # The original blocks forever for zero concurrency; avoid hanging the judge.
        return
    # Build once for validation, but execute individual requests with fresh bodies.
    results = []
    errors = []
    start_all = time.time()

    def one():
        t0 = time.time()
        try:
            req_method, req_url, req_headers, req_body, host_override = build_request(
                flags, method, url, headers_items, data, data_order, file_count)
            status, resp_headers, body = do_http_request(flags, req_method, req_url, req_headers, req_body, host_override, follow_redirects=True)
            return (time.time() - t0, status, len(body), None)
        except Exception as e:
            return (time.time() - t0, 0, 0, str(e))

    with ThreadPoolExecutor(max_workers=max(1, conc)) as ex:
        futs = [ex.submit(one) for _ in range(total_n)]
        for f in as_completed(futs):
            dur, status, size, err = f.result()
            if err:
                errors.append(err)
            else:
                results.append((dur, status, size))
    elapsed = time.time() - start_all
    durations = [r[0] for r in results]
    sizes = [r[2] for r in results]
    total_data = sum(sizes)
    fastest = min(durations) if durations else 0.0
    slowest = max(durations) if durations else 0.0
    avg = sum(durations) / len(durations) if durations else 0.0
    rps = (len(results) / elapsed) if elapsed > 0 else 0.0
    per_req = int(total_data / len(results)) if results else 0

    sys.stdout.write("\n")
    sys.stdout.write("Summary:\n")
    sys.stdout.write(f"  Total:\t{elapsed:.4f} secs.\n")
    sys.stdout.write(f"  Slowest:\t{slowest:.4f} secs.\n")
    sys.stdout.write(f"  Fastest:\t{fastest:.4f} secs.\n")
    sys.stdout.write(f"  Average:\t{avg:.4f} secs.\n")
    sys.stdout.write(f"  Requests/sec:\t{rps:.4f}\n")
    sys.stdout.write(f"  Total Data Received:\t{total_data} bytes.\n")
    sys.stdout.write(f"  Response Size per Request:\t{per_req} bytes.\n")
    sys.stdout.write("\nStatus code distribution:\n")
    counts = {}
    for _, st, _ in results:
        counts[st] = counts.get(st, 0) + 1
    for st in sorted(counts):
        sys.stdout.write(f"  [{st}]\t{counts[st]} responses\n")
    sys.stdout.write("\nResponse time histogram:\n")
    if durations:
        mn, mx = min(durations), max(durations)
        buckets = [0] * 11
        if mx == mn:
            buckets[0] = len(durations)
        else:
            for d in durations:
                idx = int(((d - mn) / (mx - mn)) * 10)
                idx = min(10, max(0, idx))
                buckets[idx] += 1
        max_bucket = max(buckets) or 1
        for i, c in enumerate(buckets):
            val = mn if mx == mn else mn + (mx - mn) * i / 10.0
            bar = '∎' * int(40 * c / max_bucket) if c else ''
            sys.stdout.write(f"  {val:.3f} [{c}]\t|{bar}\n")
    sys.stdout.write("\nLatency distribution:\n")
    if len(durations) > 1:
        for p in (10, 25, 50, 75, 90, 95, 99):
            sys.stdout.write(f"  {p}% in {percentile(durations, p):.4f} secs.\n")
    if errors:
        sys.stdout.write("\nError distribution:\n")
        ec = {}
        for e in errors:
            ec[e] = ec.get(e, 0) + 1
        for e, c in ec.items():
            sys.stdout.write(f"  [{c}]\t{e}\n")
    sys.stdout.flush()


def main(argv):
    try:
        flags, pos = parse_flags(argv)
    except FlagExit as e:
        if e.version:
            sys.stdout.write(f"Version: {VERSION}\n")
            return e.code
        if e.err:
            sys.stderr.write(e.err + "\n")
        if e.usage:
            sys.stdout.write(HELP_TEXT)
        return e.code

